fields.contract:
// Model mapping exception family in namespace ArgentSea. These exceptions signal defects in a model's mapping declarations, binary length configuration/payload width, or query/model cardinality mismatch. None is transient: retrying the same call with the same model type, parameters, and query fails the same way. Because mapping delegates are compiled lazily and cached per model type, declaration errors (InvalidMapTypeException, MapAttributeMissingException, MultipleMapAttributesException, InvalidBinaryMappingLengthException, NoMappingAttributesFoundException) surface on the first use of a model type in a given mapping direction.

public sealed class InvalidMapTypeException : ApplicationException {
  InvalidMapTypeException();
  InvalidMapTypeException(string message);
  InvalidMapTypeException(string message, Exception innerException);
  InvalidMapTypeException(PropertyInfo property, int sqlType);
  InvalidMapTypeException(string? variableName, Type type, int sqlType);
  InvalidMapTypeException(string? variableName, Type type, int sqlType, string? sqlTypeName);
  InvalidMapTypeException(PropertyInfo property, int sqlType, string? sqlTypeName);
  string? VariableName { get; }
  Type?   VariableType { get; }
  int     SqlType { get; }
}

public class MapAttributeMissingException : ApplicationException {
  public enum ShardElement { ShardId, RecordId, ChildId, GrandChildId, GreatGrandChildId }
  MapAttributeMissingException();
  MapAttributeMissingException(string message);
  MapAttributeMissingException(string message, Exception innerException);
  MapAttributeMissingException(ShardElement element, string? attributeName);
  ShardElement Element { get; }
  string? AttributeName { get; }
}

public class NoMappingAttributesFoundException : ApplicationException {
  NoMappingAttributesFoundException(); // "No mapping attributes could be found on the model class provided to the mapper."
  NoMappingAttributesFoundException(string message);
  NoMappingAttributesFoundException(string message, Exception innerException);
}

public sealed class MultipleMapAttributesException : ApplicationException {
  MultipleMapAttributesException();
  MultipleMapAttributesException(string message);
  MultipleMapAttributesException(string message, Exception innerException);
  MultipleMapAttributesException(PropertyInfo property);
  PropertyInfo? Property { get; }
}

public sealed class UnexpectedMultiRowResultException : ApplicationException {
  UnexpectedMultiRowResultException(); // "The database returned multiple records when only one was expected."
  UnexpectedMultiRowResultException(string procedureName); // "Procedure {procedureName} returned multiple records when only one was expected."
  UnexpectedMultiRowResultException(string message, Exception innerException);
}

public class InvalidBinaryMappingLengthException : ArgumentException {
  InvalidBinaryMappingLengthException(string name, Type targetType, int expectedWidth, int configuredLength, string sqlTypeName);
  string Name { get; }
  Type TargetType { get; }
  int ExpectedWidth { get; }
  int ConfiguredLength { get; }
  string SqlTypeName { get; }
}

public class InvalidBinaryValueLengthException : InvalidOperationException {
  InvalidBinaryValueLengthException(string name, Type targetType, int expectedWidth, int actualLength);
  string Name { get; }
  Type TargetType { get; }
  int ExpectedWidth { get; }
  int ActualLength { get; }
}
